async def test_post_union_with_json_name_response3_response_post_union_with_json_name() -> (
    None
):
    """Tests that jsonName works with union members."""
    client = AsyncRestJsonProtocolClient(
        config=await AsyncRestJsonProtocolConfig.resolve(
            endpoint_uri="https://example.com",
            transport=ResponseTestHTTPClient(
                status=200,
                headers=[("Content-Type", "application/json")],
                body=b'{\n    "value": {\n        "bar": "hi"\n    }\n}',
            ),
            region="us-east-1",
            aws_access_key_id="test-access-key-id",
            aws_secret_access_key="test-secret-access-key",
            aws_credentials_identity_resolver=StaticCredentialsResolver(),
        )
    )

    input_ = PostUnionWithJsonNameInput()

    try:
        actual = await client.post_union_with_json_name(input_)
    except Exception as err:
        fail(f"Expected a valid response, but received: {type(err).__name__}: {err}")
    else:
        expected = PostUnionWithJsonNameOutput(value=UnionWithJsonNameBar(value="hi"))

        assert actual == expected


